window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9dbd18a1cea77252"]={"versions": [{"id": "FIG-9dbd18a1cea77252", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (Special Data Groups und Special Data) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>SpecialData::Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe. Besitzt das Attribut <code>+ gid: NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SpecialData::SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SpecialData::SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li>Assoziation auf <code>SpecialData::SdgCaption</code> (Rolle <code>+sdgCaptionRef 0..1</code>).</li>\n<li><code>«atpMixed» SpecialData::SdgContents</code>: Dient als Container für gemischte Inhalte innerhalb einer Gruppe:</li>\n<li>Komposition auf <code>SpecialData::Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>SpecialData::Sdg</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>SpecialData::Sd</code>: Repräsentiert ein einzelnes Special-Data-Datum mit den Attributen <code>+ gid: NameToken</code> und <code>+ value: VerbatimString</code>.</li>\n<li><code>SpecialData::SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultilanguageData::MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit dem Attribut <code>+ shortName: Identifier</code>.</li>\n<li><code>MultilanguageData::MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in AUTOSAR-XML-Dateien (ARXML). Das Stereotyp <code>«atpMixed»</code> an <code>SpecialData::SdgContents</code> spezifiziert gemischten Inhalt für die XML-Darstellung. <code>SpecialData::Sd</code> transportiert unstrukturierte Textinhalte via <code>VerbatimString</code>. Über <code>+sdx</code> können beliebige <code>Referrable</code>-Elemente referenziert werden; über <code>+sdgCaption</code> bzw. <code>+sdgCaptionRef</code> wird eine Beschriftung und Beschreibung (<code>desc</code>) zugeordnet.</p>"}, {"id": "FIG-9fa3ed696e6db906", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (<code>Sdg</code> und <code>Sd</code>) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe. Besitzt das Attribut <code>+ gid :NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li>Assoziation auf <code>SdgCaption</code> (Rolle <code>+sdgCaptionRef 0..1</code>).</li>\n<li><code>«atpMixed» SdgContents</code>: Dient als Container für gemischte Inhalte innerhalb einer Gruppe:</li>\n<li>Komposition auf <code>Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>Sdg</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>Sd</code>: Repräsentiert ein einzelnes Special-Data-Datum mit den Attributen:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>+ value :VerbatimStringPlain</code></li>\n<li><code>+ xmlSpace :XmlSpaceEnum [0..1]</code></li>\n<li><code>SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit dem Attribut <code>+ shortName :Identifier</code>.</li>\n<li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in AUTOSAR-XML-Dateien (ARXML). Das Stereotyp <code>«atpMixed»</code> an <code>SdgContents</code> spezifiziert gemischten Inhalt für die XML-Darstellung. <code>Sd</code> definiert unstrukturierten Klartext über den Datentyp <code>VerbatimStringPlain</code> und steuert das Whitespace-Handling explizit über <code>xmlSpace: XmlSpaceEnum [0..1]</code>. Über <code>+sdx</code> können beliebige <code>Referrable</code>-Elemente referenziert werden; über <code>+sdgCaption</code> bzw. <code>+sdgCaptionRef</code> wird eine Beschriftung und Beschreibung (<code>desc</code>) zugeordnet.</p>"}, {"id": "FIG-a2c5d788c0cfbdba", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (<code>Sdg</code> und <code>Sd</code>) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe mit Attribut <code>+ gid :NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li>Assoziation auf <code>SdgCaption</code> (Rolle <code>+sdgCaptionRef 0..1</code>).</li>\n<li><code>«atpMixed» SdgContents</code>: Container für gemischte Inhalte mit folgenden Kindelementen und Relationen:</li>\n<li>Komposition auf <code>Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Komposition auf <code>Sdf</code> (Rolle <code>+sdf 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdxf 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>Sdg</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>Sd</code>: Repräsentiert Special Data mit String-Wert:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>+ value :VerbatimStringPlain</code></li>\n<li><code>+ xmlSpace :XmlSpaceEnum [0..1]</code></li>\n<li><code>Sdf</code>: Repräsentiert numerische Special Data mit Variation:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>«atpVariation» + value :Numerical [0..1]</code></li>\n<li><code>SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit dem Attribut <code>+ shortName :Identifier</code>.</li>\n<li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n<li>Kommentar-/Notiz-Element: <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>, gebunden über gestrichelte Linien an die Assoziation <code>+sdxf</code> sowie die rekursive Komposition <code>+sdg</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in AUTOSAR-XML-Dateien (ARXML). <code>SdgContents</code> erlaubt gemischte Inhalte (<code>«atpMixed»</code>). Neu unterstützt werden numerische Sonderdaten über <code>Sdf</code> mit optionalem, variablem Wert <code>value :Numerical [0..1]</code>. Die Variabilitätsmechanismen (<code>«atpVariation»</code>) für die Assoziation <code>+sdxf</code> und die Untergruppenkomposition <code>+sdg</code> legen über den Tag <code>vh.latestBindingTime = postBuild</code> fest, dass die späteste Bindungszeit der Variation Post-Build ist. <code>Sd</code> dient der Ablage von Textwerten (<code>VerbatimStringPlain</code>) mit <code>xmlSpace</code>-Option.</p>"}, {"id": "FIG-6bdca9565091e17d", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (<code>Sdg</code> und <code>Sd</code>) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe mit Attribut <code>+ gid :NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li>Assoziation auf <code>SdgCaption</code> (Rolle <code>+sdgCaptionRef 0..1</code>).</li>\n<li><code>«atpMixed» SdgContents</code>: Container für gemischte Inhalte mit folgenden Kindelementen und Relationen:</li>\n<li>Komposition auf <code>Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Komposition auf <code>Sdf</code> (Rolle <code>+sdf 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdxf 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>Sdg</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>Sd</code>: Repräsentiert Special Data mit String-Wert:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>+ value :VerbatimStringPlain</code></li>\n<li><code>+ xmlSpace :XmlSpaceEnum [0..1]</code></li>\n<li><code>Sdf</code>: Repräsentiert numerische Special Data mit Variation:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>«atpVariation» + value :Numerical [0..1]</code></li>\n<li><code>SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit dem Attribut <code>+ shortName :Identifier</code>.</li>\n<li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n<li>Kommentar-/Notiz-Element: <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>, gebunden über gestrichelte Linien an die Assoziation <code>+sdxf</code> sowie die rekursive Komposition <code>+sdg</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in AUTOSAR-XML-Dateien (ARXML). <code>SdgContents</code> erlaubt gemischte Inhalte (<code>«atpMixed»</code>). Neu unterstützt werden numerische Sonderdaten über <code>Sdf</code> mit optionalem, variablem Wert <code>value :Numerical [0..1]</code>. Die Variabilitätsmechanismen (<code>«atpVariation»</code>) für die Assoziation <code>+sdxf</code> und die Untergruppenkomposition <code>+sdg</code> legen über den Tag <code>vh.latestBindingTime = postBuild</code> fest, dass die späteste Bindungszeit der Variation Post-Build ist. <code>Sd</code> dient der Ablage von Textwerten (<code>VerbatimStringPlain</code>) mit <code>xmlSpace</code>-Option.</p>"}, {"id": "FIG-f78091a346086147", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (<code>Sdg</code> und <code>Sd</code>) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe mit Attribut <code>+ gid :NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li>Assoziation auf <code>SdgCaption</code> (Rolle <code>+sdgCaptionRef 0..1</code>).</li>\n<li><code>«atpMixed» SdgContents</code>: Container für gemischte Inhalte mit folgenden Kindelementen und Relationen:</li>\n<li>Komposition auf <code>Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Komposition auf <code>Sdf</code> (Rolle <code>+sdf 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdxf 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>Sdg</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>Sd</code>: Repräsentiert Special Data mit String-Wert:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>+ value :VerbatimStringPlain</code></li>\n<li><code>+ xmlSpace :XmlSpaceEnum [0..1]</code></li>\n<li><code>Sdf</code>: Repräsentiert numerische Special Data mit Variation:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>«atpVariation» + value :Numerical [0..1]</code></li>\n<li><code>SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit dem Attribut <code>+ shortName :Identifier</code>.</li>\n<li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n<li>Kommentar-/Notiz-Element: <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>, gebunden über gestrichelte Linien an die Assoziation <code>+sdxf</code> sowie die rekursive Komposition <code>+sdg</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in AUTOSAR-XML-Dateien (ARXML). <code>SdgContents</code> erlaubt gemischte Inhalte (<code>«atpMixed»</code>). Neu unterstützt werden numerische Sonderdaten über <code>Sdf</code> mit optionalem, variablem Wert <code>value :Numerical [0..1]</code>. Die Variabilitätsmechanismen (<code>«atpVariation»</code>) für die Assoziation <code>+sdxf</code> und die Untergruppenkomposition <code>+sdg</code> legen über den Tag <code>vh.latestBindingTime = postBuild</code> fest, dass die späteste Bindungszeit der Variation Post-Build ist. <code>Sd</code> dient der Ablage von Textwerten (<code>VerbatimStringPlain</code>) mit <code>xmlSpace</code>-Option.</p>"}, {"id": "FIG-64b3f482f76dbe2b", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (<code>Sdg</code> und <code>Sd</code>) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe mit Attribut <code>+ gid :NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li>Assoziation auf <code>SdgCaption</code> (Rolle <code>+sdgCaptionRef 0..1</code>).</li>\n<li><code>«atpMixed» SdgContents</code>: Container für gemischte Inhalte mit folgenden Kindelementen und Relationen:</li>\n<li>Komposition auf <code>Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Komposition auf <code>Sdf</code> (Rolle <code>+sdf 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdxf 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>Sdg</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>Sd</code>: Repräsentiert Special Data mit String-Wert:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>+ value :VerbatimStringPlain</code></li>\n<li><code>+ xmlSpace :XmlSpaceEnum [0..1]</code></li>\n<li><code>Sdf</code>: Repräsentiert numerische Special Data mit Variation:</li>\n<li><code>+ gid :NameToken</code></li>\n<li><code>«atpVariation» + value :Numerical [0..1]</code></li>\n<li><code>SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit dem Attribut <code>+ shortName :Identifier</code>.</li>\n<li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n<li>Kommentar-/Notiz-Element: <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>, gebunden über gestrichelte Linien an die Assoziation <code>+sdxf</code> sowie die rekursive Komposition <code>+sdg</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in AUTOSAR-XML-Dateien (ARXML). <code>SdgContents</code> erlaubt gemischte Inhalte (<code>«atpMixed»</code>). Neu unterstützt werden numerische Sonderdaten über <code>Sdf</code> mit optionalem, variablem Wert <code>value :Numerical [0..1]</code>. Die Variabilitätsmechanismen (<code>«atpVariation»</code>) für die Assoziation <code>+sdxf</code> und die Untergruppenkomposition <code>+sdg</code> legen über den Tag <code>vh.latestBindingTime = postBuild</code> fest, dass die späteste Bindungszeit der Variation Post-Build ist. <code>Sd</code> dient der Ablage von Textwerten (<code>VerbatimStringPlain</code>) mit <code>xmlSpace</code>-Option.</p>"}, {"id": "FIG-d8024c82ec19b411", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (<code>Sdg</code> und <code>Sd</code>) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe mit Attribut <code>+ gid: NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li><code>«atpMixed» SdgContents</code>: Container für gemischte Inhalte mit folgenden Relationen:</li>\n<li>Komposition auf <code>Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Komposition auf <code>Sdf</code> (Rolle <code>+sdf 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdxf 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>Sdg</code> mit Stereotyp <code>«atpVariation»</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>Sd</code>: Repräsentiert Special Data mit String-Wert:</li>\n<li><code>+ gid: NameToken</code></li>\n<li><code>+ value: VerbatimStringPlain</code></li>\n<li><code>+ xmlSpace: XmlSpaceEnum [0..1]</code></li>\n<li><code>Sdf</code>: Repräsentiert numerische Special Data mit Variation:</li>\n<li><code>+ gid: NameToken</code></li>\n<li><code>«atpVariation» + value: Numerical [0..1]</code></li>\n<li><code>SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit:</li>\n<li><code>«atpIdentityContributor» + shortName: Identifier</code></li>\n<li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n<li>Notiz-Element: <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>, annotiert an <code>+sdxf</code> und <code>+sdg</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in ARXML. <code>Referrable::shortName</code> ist mit dem Stereotyp <code>«atpIdentityContributor»</code> versehen und fungiert damit normativ als identitätsstiftendes Attribut für das Element im AUTOSAR-Namensraum. Die Zuordnung von <code>Sdg</code> zu <code>SdgCaption</code> erfolgt ausschließlich über die Komposition <code>+sdgCaption 0..1</code>; eine parallele Referenzierung über <code>sdgCaptionRef</code> entfällt im Metamodell. Variabilitätsmechanismen mit <code>postBuild</code>-Bindung gelten für <code>+sdg</code> und <code>+sdxf</code>.</p>"}, {"id": "FIG-3e394596eebc4184", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Metamodell-Spezifikation der generischen Datenstruktur <code>SpecialData</code> im Rahmen des AUTOSAR-Templates <code>AUTOSAR_TPS_GenericStructureTemplate</code>. Es modelliert die Struktur zur Erfassung herstellerspezifischer oder proprietärer Datenstrukturen (<code>Sdg</code> und <code>Sd</code>) innerhalb von AUTOSAR-Modellen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm umfasst folgende Metaklassen und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><code>Sdg</code>: Zentrales Wurzelelement einer Special-Data-Gruppe mit Attribut <code>+ gid: NameToken</code>.</li>\n<li>Komposition auf <code>«atpMixed» SdgContents</code> (Rolle <code>+sdgContentsType 0..1</code>).</li>\n<li>Komposition auf <code>SdgCaption</code> (Rolle <code>+sdgCaption 0..1</code>).</li>\n<li><code>«atpMixed» SdgContents</code>: Container für gemischte Inhalte mit folgenden Relationen:</li>\n<li>Komposition auf <code>Sd</code> (Rolle <code>+sd 0..1</code>).</li>\n<li>Komposition auf <code>Sdf</code> (Rolle <code>+sdf 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> (Rolle <code>+sdx 0..1</code>).</li>\n<li>Gerichtete Assoziation auf <code>Referrable</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code> (Rolle <code>+sdxf 0..1</code>).</li>\n<li>Rekursive Komposition auf <code>Sdg</code> mit Stereotyp <code>«atpVariation,atpSplitable»</code> (Rolle <code>+sdg 0..1</code>).</li>\n<li><code>Sd</code>: Repräsentiert Special Data mit String-Wert:</li>\n<li><code>+ gid: NameToken</code></li>\n<li><code>+ value: VerbatimStringPlain</code></li>\n<li><code>+ xmlSpace: XmlSpaceEnum [0..1]</code></li>\n<li><code>Sdf</code>: Repräsentiert numerische Special Data mit Variation:</li>\n<li><code>+ gid: NameToken</code></li>\n<li><code>«atpVariation» + value: Numerical [0..1]</code></li>\n<li><code>SdgCaption</code>: Erbt von <code>MultilanguageReferrable</code>. Enthält eine Komposition auf <code>MultiLanguageOverviewParagraph</code> (Rolle <code>+desc 0..1</code>).</li>\n<li><code>Referrable</code>: Abstrakte Basisklasse mit:</li>\n<li><code>«atpIdentityContributor» + shortName: Identifier</code></li>\n<li><code>MultiLanguageOverviewParagraph</code>: Repräsentiert mehrsprachige Textbeschreibungen.</li>\n<li>Notiz-Element: <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code>, annotiert an <code>+sdxf</code> und <code>+sdg</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statisches Metamodell ohne dynamische Sequenz- oder Laufzeitverhaltensanteile. Es definiert die statische Schachtelungshierarchie und Referenzierungsregeln für generische Metadaten.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für Serialisierung und Strukturierung von <code>SpecialData</code> in ARXML. <code>Referrable::shortName</code> ist mit dem Stereotyp <code>«atpIdentityContributor»</code> versehen und fungiert damit normativ als identitätsstiftendes Attribut für das Element im AUTOSAR-Namensraum. Die Zuordnung von <code>Sdg</code> zu <code>SdgCaption</code> erfolgt ausschließlich über die Komposition <code>+sdgCaption 0..1</code>; eine parallele Referenzierung über <code>sdgCaptionRef</code> entfällt im Metamodell. Variabilitäts- und Aufteilungsmechanismen (<code>«atpVariation,atpSplitable»</code>) mit <code>postBuild</code>-Bindung gelten für <code>+sdg</code> und <code>+sdxf</code>.</p>"}], "trans": [{"from": "FIG-9dbd18a1cea77252", "to": "FIG-9fa3ed696e6db906", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In Klasse <code>Sd</code>: Attribut <code>value</code> vom Datentyp <code>VerbatimString</code> auf <code>VerbatimStringPlain</code> geändert.</li>\n<li>In Klasse <code>Sd</code>: Optionales Attribut <code>xmlSpace: XmlSpaceEnum [0..1]</code> hinzugefügt.</li>\n<li>Paketpräfixe (<code>SpecialData::</code>, <code>MultilanguageData::</code>) in den Klassennamen (<code>Sdg</code>, <code>SdgContents</code>, <code>Sd</code>, <code>SdgCaption</code>, <code>MultiLanguageOverviewParagraph</code>) entfernt.</li>\n<li>Anordnung/Layout der Rollennamen und Multiplizitäten redaktionell bereinigt.</li>\n</ul>"}, {"from": "FIG-9fa3ed696e6db906", "to": "FIG-a2c5d788c0cfbdba", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Neue Klasse <code>Sdf</code> eingeführt mit Attributen <code>+ gid: NameToken</code> und <code>«atpVariation» + value: Numerical [0..1]</code>.</li>\n<li>Kompositionsbeziehung von <code>SdgContents</code> zu <code>Sdf</code> mit Rolle <code>+sdf 0..1</code> ergänzt.</li>\n<li>Assoziationsbeziehung von <code>SdgContents</code> zu <code>Referrable</code> mit Stereotyp <code>«atpVariation»</code> und Rolle <code>+sdxf 0..1</code> ergänzt.</li>\n<li>Rekursive Kompositionsbeziehung von <code>SdgContents</code> zu <code>Sdg</code> (Rolle <code>+sdg 0..1</code>) mit Stereotyp <code>«atpVariation»</code> versehen.</li>\n<li>Tagged-Value-Kommentar <code>«atpVariation» Tags: vh.latestBindingTime = postBuild</code> eingeführt, annotiert an die variablen Beziehungen <code>+sdg</code> und <code>+sdxf</code>.</li>\n</ul>"}, {"from": "FIG-a2c5d788c0cfbdba", "to": "FIG-6bdca9565091e17d", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6bdca9565091e17d", "to": "FIG-f78091a346086147", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f78091a346086147", "to": "FIG-64b3f482f76dbe2b", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-64b3f482f76dbe2b", "to": "FIG-d8024c82ec19b411", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>In Klasse <code>Referrable</code>: Stereotyp <code>«atpIdentityContributor»</code> oberhalb des Attributs <code>shortName</code> ergänzt.</li>\n<li>Assoziation von <code>Sdg</code> zu <code>SdgCaption</code> mit Rolle <code>+sdgCaptionRef 0..1</code> entfernt.</li>\n</ul>"}, {"from": "FIG-d8024c82ec19b411", "to": "FIG-3e394596eebc4184", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Stereotyp an der rekursiven Komposition von <code>SdgContents</code> auf <code>Sdg</code> (Rolle <code>+sdg 0..1</code>) von <code>«atpVariation»</code> zu <code>«atpVariation,atpSplitable»</code> erweitert.</li>\n<li>Stereotyp an der gerichteten Assoziation von <code>SdgContents</code> auf <code>Referrable</code> (Rolle <code>+sdxf 0..1</code>) von <code>«atpVariation»</code> zu <code>«atpVariation,atpSplitable»</code> erweitert.</li>\n</ul>"}]};
